def q421(
    message_bytes, workers, bandwidth_bytes_per_second, latency_seconds
):
    if workers < 1 or bandwidth_bytes_per_second <= 0:
        raise ValueError("invalid hardware")
    return (
        2 * (workers - 1) * latency_seconds
        + 2
        * (workers - 1)
        / workers
        * message_bytes
        / bandwidth_bytes_per_second
    )
